template <int K>
__device__ __forceinline__ void register_cholesky_step_32(
    float (&row_values)[32],
    int lane
) {
    float value = row_values[K];
    #pragma unroll
    for (int j = 0; j < K; ++j) {
        const float pivot = __shfl_sync(0xffffffff, row_values[j], K);
        if (lane >= K) {
            value = fmaf(-row_values[j], pivot, value);
        }
    }

    float inverse = 0.0f;
    if (lane == K) {
        value = sqrtf(fmaxf(value, 1.0e-30f));
        row_values[K] = value;
        inverse = 1.0f / value;
    }
    inverse = __shfl_sync(0xffffffff, inverse, K);
    if (lane > K) {
        row_values[K] = value * inverse;
    }
    if constexpr (K + 1 < 32) {
        register_cholesky_step_32<K + 1>(row_values, lane);
    }
}

__global__ void grouped_warp_cholesky_32(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 32;
    constexpr int LD = 33;
    constexpr int MATRICES_PER_BLOCK = 4;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + warp;
    if (matrix >= batch) {
        return;
    }

    float* tile = storage + warp * N * LD;
    const long long base = static_cast<long long>(matrix) * N * N;
    const float* src = input + base;
    float* dst = output + base;
    #pragma unroll
    for (int row = 0; row < N; ++row) {
        tile[row * LD + lane] = row >= lane
            ? src[row * N + lane]
            : 0.0f;
    }
    __syncwarp();

    float row_values[N];
    #pragma unroll
    for (int col = 0; col < N; ++col) {
        row_values[col] = tile[lane * LD + col];
    }
    register_cholesky_step_32<0>(row_values, lane);

    #pragma unroll
    for (int col = 0; col < N; ++col) {
        tile[lane * LD + col] = row_values[col];
    }
    __syncwarp();

    #pragma unroll
    for (int row = 0; row < N; ++row) {
        dst[row * N + lane] = tile[row * LD + lane];
    }
}

template <int K>
__device__ __forceinline__ void register_cholesky_step_64(
    float (&row_values)[64],
    float* tile,
    float* inverse,
    int group,
    int lane,
    bool active
) {
    constexpr int LD = 65;
    float value = 0.0f;
    if (active && lane >= K) {
        value = row_values[K];
        #pragma unroll
        for (int j = 0; j < K; ++j) {
            value = fmaf(-row_values[j], tile[K * LD + j], value);
        }
    }

    if (active && lane == K) {
        const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
        row_values[K] = diagonal;
        tile[K * LD + K] = diagonal;
        inverse[group] = 1.0f / diagonal;
    }
    __syncthreads();

    if (active && lane > K) {
        value *= inverse[group];
        row_values[K] = value;
        tile[lane * LD + K] = value;
    }
    __syncthreads();

    if constexpr (K + 1 < 64) {
        register_cholesky_step_64<K + 1>(
            row_values, tile, inverse, group, lane, active
        );
    }
}

__global__ void grouped_two_cholesky_64(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 64;
    constexpr int LD = 65;
    constexpr int MATRICES_PER_BLOCK = 2;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    __shared__ float inverse[MATRICES_PER_BLOCK];
    const int group = threadIdx.x / N;
    const int lane = threadIdx.x % N;
    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + group;
    const bool active = matrix < batch;
    float* tile = storage + group * N * LD;

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        const float* src = input + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            tile[row * LD + lane] = row >= lane
                ? src[row * N + lane]
                : 0.0f;
        }
    }
    __syncthreads();

    float row_values[N];
    #pragma unroll
    for (int col = 0; col < N; ++col) {
        row_values[col] = active ? tile[lane * LD + col] : 0.0f;
    }
    register_cholesky_step_64<0>(
        row_values, tile, inverse, group, lane, active
    );

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        float* dst = output + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            dst[row * N + lane] = tile[row * LD + lane];
        }
    }
}

__device__ __forceinline__ void factor_panel_16_warp(
    float* tile,
    int panel
) {
    constexpr int N = 128;
    const int lane = threadIdx.x % 32;
    if (lane < 16) {
        float row_values[16];
        #pragma unroll
        for (int col = 0; col < 16; ++col) {
            row_values[col] = lane >= col
                ? tile[(panel + lane) * N + panel + col]
                : 0.0f;
        }

        #pragma unroll
        for (int pivot = 0; pivot < 16; ++pivot) {
            float value = row_values[pivot];
            #pragma unroll
            for (int col = 0; col < pivot; ++col) {
                const float pivot_value = __shfl_sync(
                    0x0000ffff, row_values[col], pivot, 16
                );
                if (lane >= pivot) {
                    value = fmaf(-row_values[col], pivot_value, value);
                }
            }
            float inverse = 0.0f;
            if (lane == pivot) {
                const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
                row_values[pivot] = diagonal;
                inverse = 1.0f / diagonal;
            }
            inverse = __shfl_sync(0x0000ffff, inverse, pivot, 16);
            if (lane > pivot) {
                row_values[pivot] = value * inverse;
            }
        }

        #pragma unroll
        for (int col = 0; col < 16; ++col) {
            if (lane >= col) {
                tile[(panel + lane) * N + panel + col] = row_values[col];
            }
        }
    }
}

__device__ __forceinline__ void factor_panel_16(
    float* tile,
    int panel
) {
    if (threadIdx.x / 32 == 0) {
        factor_panel_16_warp(tile, panel);
    }
    __syncthreads();
}

__device__ __forceinline__ void solve_panel_16(
    float* tile,
    int panel
) {
    constexpr int N = 128;
    constexpr int TEAM_WIDTH = 4;
    const int team = threadIdx.x / TEAM_WIDTH;
    const int lane = threadIdx.x % TEAM_WIDTH;
    const int stop = panel + 16;
    const int row = stop + team;
    const bool active = row < N;
    float row_values[4];
    #pragma unroll
    for (int item = 0; item < 4; ++item) {
        row_values[item] = active
            ? tile[row * N + panel + item * TEAM_WIDTH + lane]
            : 0.0f;
    }
    #pragma unroll
    for (int pivot = 0; pivot < 16; ++pivot) {
        float dot = 0.0f;
        #pragma unroll
        for (int item = 0; item < 4; ++item) {
            const int col = item * TEAM_WIDTH + lane;
            if (col < pivot) {
                dot = fmaf(
                    row_values[item],
                    tile[(panel + pivot) * N + panel + col],
                    dot
                );
            }
        }
        dot += __shfl_down_sync(0xffffffff, dot, 2, TEAM_WIDTH);
        dot += __shfl_down_sync(0xffffffff, dot, 1, TEAM_WIDTH);
        float original = __shfl_sync(
            0xffffffff,
            row_values[pivot / TEAM_WIDTH],
            pivot % TEAM_WIDTH,
            TEAM_WIDTH
        );
        float solved = lane == 0
            ? (original - dot)
                / tile[(panel + pivot) * N + panel + pivot]
            : 0.0f;
        solved = __shfl_sync(0xffffffff, solved, 0, TEAM_WIDTH);
        if (lane == pivot % TEAM_WIDTH) {
            row_values[pivot / TEAM_WIDTH] = solved;
        }
    }
    if (active) {
        #pragma unroll
        for (int item = 0; item < 4; ++item) {
            tile[row * N + panel + item * TEAM_WIDTH + lane] =
                row_values[item];
        }
    }
    __syncthreads();
}

__device__ __forceinline__ void compensated_rankk_16(
    float* tile,
    int panel
) {
    constexpr int N = 128;
    constexpr int WARPS = 16;
    constexpr int MMA_M = 16;
    constexpr int MMA_N = 16;
    constexpr int MMA_K = 8;
    constexpr float RESIDUAL_SCALE = 32.0f;
    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
    const int warp = threadIdx.x / 32;
    const int stop = panel + 16;
    const int tile_count = (N - stop) / MMA_M;
    int ordinal = 0;
    for (int block_row = 0; block_row < tile_count; ++block_row) {
        for (int block_col = 0; block_col <= block_row; ++block_col) {
            if (ordinal % WARPS == warp) {
                {
                wmma::fragment<
                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::row_major
                > a_high;
                wmma::fragment<
                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::row_major
                > a_scaled;
                wmma::fragment<
                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::col_major
                > b_high;
                wmma::fragment<
                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::col_major
                > b_scaled;
                wmma::fragment<
                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
                > high_product;
                wmma::fragment<
                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
                > scaled_product;
                wmma::fragment<
                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
                > accumulator;
                wmma::fill_fragment(high_product, 0.0f);
                wmma::fill_fragment(scaled_product, 0.0f);
                #pragma unroll
                for (int offset = 0; offset < 16; offset += MMA_K) {
                    wmma::load_matrix_sync(
                        a_high,
                        tile + (stop + block_row * MMA_M) * N
                            + panel + offset,
                        N
                    );
                    wmma::load_matrix_sync(
                        b_high,
                        tile + (stop + block_col * MMA_N) * N
                            + panel + offset,
                        N
                    );
                    #pragma unroll
                    for (int element = 0;
                         element < a_high.num_elements;
                         ++element) {
                        const float original = a_high.x[element];
                        const float high = wmma::__float_to_tf32(original);
                        a_high.x[element] = high;
                        a_scaled.x[element] = wmma::__float_to_tf32(
                            fmaf(RESIDUAL_SCALE, original - high, high)
                        );
                    }
                    #pragma unroll
                    for (int element = 0;
                         element < b_high.num_elements;
                         ++element) {
                        const float original = b_high.x[element];
                        const float high = wmma::__float_to_tf32(original);
                        b_high.x[element] = high;
                        b_scaled.x[element] = wmma::__float_to_tf32(
                            fmaf(RESIDUAL_SCALE, original - high, high)
                        );
                    }
                    wmma::mma_sync(
                        high_product, a_high, b_high, high_product
                    );
                    wmma::mma_sync(
                        scaled_product,
                        a_scaled,
                        b_scaled,
                        scaled_product
                    );
                }
                wmma::load_matrix_sync(
                    accumulator,
                    tile + (stop + block_row * MMA_M) * N
                        + stop + block_col * MMA_N,
                    N,
                    wmma::mem_row_major
                );
                #pragma unroll
                for (int element = 0;
                     element < accumulator.num_elements;
                     ++element) {
                    const float correction = (
                        scaled_product.x[element]
                        - high_product.x[element]
                    ) * INVERSE_RESIDUAL_SCALE;
                    accumulator.x[element] -=
                        high_product.x[element] + correction;
                }
                wmma::store_matrix_sync(
                    tile + (stop + block_row * MMA_M) * N
                        + stop + block_col * MMA_N,
                    accumulator,
                    N,
                    wmma::mem_row_major
                );
                }
            }
            ++ordinal;
        }
    }
    if (warp == 0) {
        factor_panel_16_warp(tile, stop);
    }
    __syncthreads();
}

