    }

        data_view, output_view, flag_view, epoch
    )


_d256_output_cache = {}
_d256_last_input = None
_d256_last_entry = None
_d256_epoch = 0


def _run_d256(data: torch.Tensor) -> torch.Tensor:
    global _d256_last_input, _d256_last_entry, _d256_epoch
    if _d256_last_input is data:
        entry = _d256_last_entry
    else:
        key = id(data)
        entry = _d256_output_cache.get(key)
        if entry is None or entry[0] is not data:
            output = torch.zeros_like(
                data, memory_format=torch.contiguous_format
            )
            flags = torch.zeros(
                data.shape[0] * 2,
                device=data.device,
                dtype=torch.int32,
            )
            entry = (
                data,
                output,
                _as_numba_flat_array(data),
                _as_numba_flat_array(output),
                flags,
                _as_numba_int32_array(flags),
                output.transpose(-2, -1),
            )
            _d256_output_cache[key] = entry
        _d256_last_input = data
        _d256_last_entry = entry
    _d256_epoch += 1
    _launch_d256(
        entry[2], entry[3], entry[5], np.int32(_d256_epoch), data.shape[0]
    )
    return entry[6]


# Exact batch-2 N=4096 wavefront.  Each launch factors one 64-wide panel on
# device, then keeps 64 CTAs per matrix resident while they solve disjoint
# 64-column panel shards.  The caller-queue kernel boundary orders the
# following triangular CuTe rank-k update without a host synchronization.
_B4096_N = 4096
_B4096_NB = 64
_B4096_PANEL_TILES = 8
_B4096_PANEL_WIDTH = _B4096_PANEL_TILES * _B4096_NB
_B4096_NT = 128
_B4096_WORKERS = 64
_B4096_TILE_ELEMENTS = _B4096_NB * _B4096_NB
_B4096_LOADS_PER_THREAD = _B4096_TILE_ELEMENTS // _B4096_NT
_B4096_ROW_STRIDE = _B4096_NT // _B4096_NB
_B4096_GLOBAL_ROW_STRIDE = _B4096_ROW_STRIDE * _B4096_N
_B4096_SHARED_BYTES = 3 * _B4096_TILE_ELEMENTS * 4 + 4


@cuda.jit(device=True, forceinline=True)
def _b4096_load_diagonal(output, sample_base, panel_origin, shared):
    tid = cuda.threadIdx.x
    row = tid // _B4096_NB
    col = tid - row * _B4096_NB
    index = tid
    source_index = sample_base + (panel_origin + row) * _B4096_N + panel_origin + col
    for _ in range(_B4096_LOADS_PER_THREAD):
        if row <= col:
            shared[index] = output[source_index]
        row += _B4096_ROW_STRIDE
        index += _B4096_NT
        source_index += _B4096_GLOBAL_ROW_STRIDE
    cuda.syncthreads()


@cuda.jit(device=True, forceinline=True)
def _b4096_load_panel(output, sample_base, panel_origin, panel_col, shared):
    tid = cuda.threadIdx.x
    row = tid // _B4096_NB
    col = tid - row * _B4096_NB
    index = tid
    source_index = sample_base + (panel_origin + row) * _B4096_N + panel_col + col
    for _ in range(_B4096_LOADS_PER_THREAD):
        shared[index] = output[source_index]
        index += _B4096_NT
        source_index += _B4096_GLOBAL_ROW_STRIDE
    cuda.syncthreads()


@cuda.jit(device=True, forceinline=True)
def _b4096_store_tile(
    shared, output, sample_base, row_origin, col_origin, triangular
):
    cuda.syncthreads()
    tid = cuda.threadIdx.x
    row = tid // _B4096_NB
    col = tid - row * _B4096_NB
    index = tid
    destination_index = sample_base + (row_origin + row) * _B4096_N + col_origin + col
    for _ in range(_B4096_LOADS_PER_THREAD):
        if not triangular or row <= col:
            output[destination_index] = shared[index]
        row += _B4096_ROW_STRIDE
        index += _B4096_NT
        destination_index += _B4096_GLOBAL_ROW_STRIDE


@cuda.jit
def _b4096_factor_solve_stage(output, flags, epoch, panel_origin):
    sample = cuda.blockIdx.x // _B4096_WORKERS
    worker = cuda.blockIdx.x - sample * _B4096_WORKERS
    sample_base = sample * (_B4096_N * _B4096_N)
    shared = cuda.shared.array(shape=0, dtype=np.float32, alignment=16)
    factor = shared[0:_B4096_TILE_ELEMENTS]
    panel = shared[_B4096_TILE_ELEMENTS : 2 * _B4096_TILE_ELEMENTS]
    update = shared[
        2 * _B4096_TILE_ELEMENTS : 3 * _B4096_TILE_ELEMENTS
    ].view(np.float16)
    first = update[0:_B4096_TILE_ELEMENTS]
    second = update[_B4096_TILE_ELEMENTS : 2 * _B4096_TILE_ELEMENTS]
    local_info = shared[3 * _B4096_TILE_ELEMENTS :].view(np.int32)

    remaining_tiles = (_B4096_N - panel_origin) // _B4096_NB
    for k in range(_B4096_PANEL_TILES):
        local_origin = panel_origin + k * _B4096_NB
        if worker == 0:
            if cuda.threadIdx.x == 0:
                cuda.atomic.exch(flags, sample * 2 + 1, 0)
            _b4096_load_diagonal(output, sample_base, local_origin, factor)
            for previous in range(k):
                previous_origin = (
                    panel_origin + previous * _B4096_NB
                )
                _b4096_load_panel(
                    output,
                    sample_base,
                    previous_origin,
                    local_origin,
                    first,
                )
                _d256_gemm.execute(-1.0, first, first, 1.0, factor)
                cuda.syncthreads()
            _d256_cholesky.factorize(
                factor, local_info, lda=_B4096_NB
            )
            _b4096_store_tile(
                factor,
                output,
                sample_base,
                local_origin,
                local_origin,
                True,
            )
            cuda.syncthreads()
            if cuda.threadIdx.x == 0:
                cuda.threadfence()
                cuda.atomic.exch(
                    flags,
                    sample * 2,
                    epoch * _B4096_PANEL_TILES + k + 1,
                )
        else:
            if cuda.threadIdx.x == 0:
                token = epoch * _B4096_PANEL_TILES + k + 1
                while cuda.atomic.add(flags, sample * 2, 0) != token:
                    pass
        cuda.syncthreads()

        panel_col = panel_origin + (k + worker + 1) * _B4096_NB
        has_panel = panel_col < _B4096_N
        if has_panel:
            if worker != 0:
                _b4096_load_diagonal(
                    output, sample_base, local_origin, factor
                )
            _b4096_load_panel(
                output, sample_base, local_origin, panel_col, panel
            )
            for previous in range(k):
                previous_origin = (
                    panel_origin + previous * _B4096_NB
                )
                _b4096_load_panel(
                    output,
                    sample_base,
                    previous_origin,
                    local_origin,
                    first,
                )
                _b4096_load_panel(
                    output,
                    sample_base,
                    previous_origin,
                    panel_col,
                    second,
                )
                _d256_gemm.execute(-1.0, first, second, 1.0, panel)
                cuda.syncthreads()
            _d256_triangular.solve(
                factor, panel, lda=_B4096_NB, ldb=_B4096_NB
            )
            _b4096_store_tile(
                panel,
                output,
                sample_base,
                local_origin,
                panel_col,
                False,
            )
            cuda.syncthreads()
            cuda.threadfence()
            if cuda.threadIdx.x == 0:
                cuda.atomic.add(flags, sample * 2 + 1, 1)
        if cuda.threadIdx.x == 0 and worker == 0 and has_panel:
            active_workers = min(
                _B4096_WORKERS, remaining_tiles - k - 1
            )
            while (
                cuda.atomic.add(flags, sample * 2 + 1, 0)
                < active_workers
            ):
                pass
        cuda.syncthreads()

