    data: torch.Tensor,
    output: torch.Tensor,
    pointers: torch.Tensor,
    output_view,
) -> torch.Tensor:
    global _g2048_epoch
    n = output.shape[-1]
    block = _G2048_N
    key = id(output)
    stage_entry = _g2048_stage_cache.get(key)
    if stage_entry is None or stage_entry[0] is not output:
